            name: data.name,
            emailVerified: data.emailVerified,
            image: data.image,
            updatedAt: data.updatedAt,
          })
          .where(eq(users.id, data.id)).returning();

        if (!result) {
          return data;
        }
        return result as IUserDBDTO;
      }
    });

