          amount,
          entryType,
        });

        return entry;
      },
      errorMessage: "FAILED_TO_CREATE_LEDGER_ENTRY",
    });

    tryCatch({
      ctx: async () => {
        await this.cacheManager.set(
          data.id,
          data,
          5 * 60 
